#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Agrega un icono CUADRADO (solo el simbolo de la luna/O) para la pantalla de
inicio de iOS/Android, separado del logo ancho que se usa dentro de la app.
Esto corrige que el icono se viera gigante y descuadrado al agregar la app
a la pantalla de inicio (iOS recortaba el logo ancho de forma forzada).
Uso: cd ~/inventario && python3 agregar_icono_cuadrado.py
"""
import os, re, base64, time

STATIC = os.path.expanduser('~/inventario/static')

ICON_B64 = ''

version = str(int(time.time()))

# ================================================================
# 1. Guardar el icono cuadrado
# ================================================================
print("1. Guardando static/icon-square.png...")
icon_path = os.path.join(STATIC, 'icon-square.png')
with open(icon_path, 'wb') as f:
    f.write(base64.b64decode(ICON_B64))
print("   OK icon-square.png guardado (" + str(os.path.getsize(icon_path)) + " bytes)")

# ================================================================
# 2. Agregar <link rel="apple-touch-icon"> y actualizar el favicon
#    en TODAS las paginas HTML (para que la pantalla de inicio use
#    el icono cuadrado en vez del logo ancho recortado)
# ================================================================
print("2. Actualizando referencias de icono en todas las paginas...")
archivos = [f for f in os.listdir(STATIC) if f.endswith('.html')]
total = 0

for archivo in archivos:
    ruta = os.path.join(STATIC, archivo)
    src = open(ruta, encoding='utf-8').read()
    original = src

    # Quitar apple-touch-icon previos (por si se corrio antes) para no duplicar
    src = re.sub(r'\s*<link rel="apple-touch-icon"[^>]*>\n?', '', src)

    nuevo_link = '<link rel="apple-touch-icon" href="/static/icon-square.png?v=' + version + '">'

    if '<link rel="icon"' in src:
        # Reemplazar el favicon existente para que tambien use el icono cuadrado
        src = re.sub(
            r'<link rel="icon"[^>]*>',
            '<link rel="icon" type="image/png" href="/static/icon-square.png?v=' + version + '">\n' + nuevo_link,
            src, count=1
        )
    else:
        # Si no habia favicon, agregarlo despues del <meta charset>
        src = src.replace(
            '<meta charset="UTF-8">',
            '<meta charset="UTF-8">\n<link rel="icon" type="image/png" href="/static/icon-square.png?v=' + version + '">\n' + nuevo_link,
            1
        )

    if src != original:
        open(ruta, 'w', encoding='utf-8').write(src)
        total += 1
        print("   OK " + archivo)

print("   Total: " + str(total) + " paginas actualizadas")

print()
print("=" * 50)
print("Reiniciando el servicio...")
os.system("sudo systemctl restart inventario")
print()
print("Listo. En el iPad/iPhone:")
print("  1. Si ya tenias la app agregada a la pantalla de inicio, BORRA ese icono")
print("     (mantener presionado -> Eliminar app / Quitar de inicio)")
print("  2. Abre la app en Safari de nuevo")
print("  3. Compartir -> 'Agregar a pantalla de inicio' otra vez")
print("  4. El nuevo icono cuadrado (solo el simbolo O) debe verse correctamente")
